def is_subsequence(t, s):
    """Check if t is a subsequence of s"""
    it = iter(s)
    return all(c in it for c in t)

s = input().strip()
t = input().strip()

max_length = 0

# Try removing each possible substring
for i in range(len(s)):
    for j in range(i, len(s)):
        # Remove substring s[i:j+1]
        remaining = s[:i] + s[j+1:]

        # Check if t is still a subsequence
        if is_subsequence(t, remaining):
            max_length = max(max_length, j - i + 1)

print(max_length)
