import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    b = int(data[1])
    prices = list(map(int, data[2:2+n]))

    max_money = b  # At least we can do nothing

    for i in range(n):
        for j in range(i + 1, n):
            # Buy on day i, sell on day j
            dollars = b // prices[i]
            remainder = b % prices[i]
            final_money = remainder + dollars * prices[j]

            if final_money > max_money:
                max_money = final_money

    print(max_money)

if __name__ == "__main__":
    solve()
"}

