import sys

def solve():
    n = int(sys.stdin.readline())
    requests = []
    for _ in range(n):
        si, di = map(int, sys.stdin.readline().split())
        requests.append((si, di))

    # Track occupied days
    occupied = set()

    for si, di in requests:
        # Check if preferred slot is free
        free = True
        for day in range(si, si + di):
            if day in occupied:
                free = False
                break

        if free:
            # Use preferred slot
            start = si
            end = si + di - 1
            for day in range(start, end + 1):
                occupied.add(day)
            print(start, end)
        else:
            # Find the smallest x such that x to x+di-1 is free
            x = 1
            while True:
                free = True
                for day in range(x, x + di):
                    if day in occupied:
                        free = False
                        break
                if free:
                    break
                x += 1

            # Use found slot
            start = x
            end = x + di - 1
            for day in range(start, end + 1):
                occupied.add(day)
            print(start, end)

if __name__ == "__main__":
    solve()
"}

