import sys
import math

def modinv(a, m):
    """Modular multiplicative inverse using Fermat's little theorem"""
    return pow(a, m - 2, m)

def comb(n, k, fact, inv_fact, mod):
    """Compute combination C(n, k) modulo mod"""
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

def solve():
    MOD = 10**9 + 7

    # Precompute factorials and inverse factorials up to 2*10^6 + 10
    max_n = 2 * 10**6 + 10
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = modinv(fact[max_n], MOD)
    for i in range(max_n, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    q = int(data[0])
    idx = 1

    for _ in range(q):
        x = int(data[idx])
        y = int(data[idx+1])
        idx += 2

        # Factorize x
        factors = {}
        temp = x
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                factors[p] = count
        if temp > 1:
            factors[temp] = 1

        # Compute combinations for each prime factor
        result = 1
        for p, e in factors.items():
            # C(e + y - 1, y - 1)
            result = result * comb(e + y - 1, y - 1, fact, inv_fact, MOD) % MOD

        # Multiply by 2^(y-1)
        result = result * pow(2, y-1, MOD) % MOD

        print(result)

if __name__ == "__main__":
    solve()
"}

