import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    min_temp = int(data[2])
    max_temp = int(data[3])

    # Extract the reported temperatures
    reported = list(map(int, data[4:4+m]))

    # Check if we can add the required temperatures
    min_in_reported = min_temp in reported
    max_in_reported = max_temp in reported

    # Check if we have enough missing temperatures
    if not min_in_reported and not max_in_reported:
        # Need at least 2 missing temperatures
        if (n - m) >= 2:
            print("Correct")
        else:
            print("Incorrect")
    elif not min_in_reported or not max_in_reported:
        # Need at least 1 missing temperature
        if (n - m) >= 1:
            print("Correct")
        else:
            print("Incorrect")
    else:
        # Both min and max are already in reported
        print("Correct")

if __name__ == "__main__":
    solve()
"}

