def count_valid_combinations(n, balls):
    """Count the number of valid combinations where Jerry wins round 3 and Andrew wins rounds 1 and 2."""
    count = 0
    # For round 1, we need a pair (a1, j1) where a1 > j1
    # For round 2, we need a pair (a2, j2) where a2 > j2
    # For round 3, we need a pair (a3, j3) where j3 > a3

    # Iterate through all possible pairs for each round
    for a1, j1 in combinations_with_larger_first(balls):
        for a2, j2 in combinations_with_larger_first(balls):
            for a3, j3 in combinations_with_larger_second(balls):
                # Check if all balls are distinct
                if len({a1, j1, a2, j2, a3, j3}) == 6:
                    # Check if Jerry's total is greater than Andrew's
                    if (j1 + j2 + j3) > (a1 + a2 + a3):
                        count += 1

    return count

def combinations_with_larger_first(balls):
    """Return all pairs (larger, smaller) where larger > smaller."""
    result = []
    for i in range(len(balls)):
        for j in range(len(balls)):
            if i != j:
                if balls[i] > balls[j]:
                    result.append((balls[i], balls[j]))
    return result

def combinations_with_larger_second(balls):
    """Return all pairs (smaller, larger) where larger > smaller."""
    result = []
    for i in range(len(balls)):
        for j in range(len(balls)):
            if i != j:
                if balls[i] > balls[j]:
                    result.append((balls[j], balls[i]))
    return result

def solve():
    n = int(input())
    balls = list(map(int, input().split()))

    total_valid = 0

    # Count combinations where Jerry wins round 3 and Andrew wins rounds 1 and 2
    total_valid = count_valid_combinations(n, balls)

    # Total possible outcomes
    # For each round, we can choose any pair (with replacement)
    total_outcomes = (n * (n - 1) // 2) ** 3  # C(n, 2) for each round

    probability = total_valid / total_outcomes

    # Print with 10 decimal places
    print(f"{probability:.10f}")

