from collections import defaultdict

def solve():
    n = int(input())
    s = input()

    # DP: dp[i][last_char][count_v][count_k] = min_swaps
    # i: number of characters placed
    # last_char: 0 = 'V', 1 = 'K', 2 = other
    # count_v: number of 'V's placed so far
    # count_k: number of 'K's placed so far
    # This might be too large for n=75

    # Instead, let's use a more efficient DP
    # dp[i][last][v][k] = min_swaps
    # i: number of characters placed
    # last: 0 = 'V', 1 = 'K', 2 = other
    # v: number of 'V's placed
    # k: number of 'K's placed

    # Since n <= 75, and v + k <= n, this might be feasible
    INF = float('inf')
    dp = [[[[INF] * (n + 1) for _ in range(n + 1)] for _ in range(3)] for _ in range(n + 1)]

    # Initialize: no characters placed, last is 'other', 0 'V's, 0 'K's
    dp[0][2][0][0] = 0

    # Count characters
    count = [0] * 3
    for c in s:
        if c == 'V':
            count[0] += 1
        elif c == 'K':
            count[1] += 1
        else:
            count[2] += 1

    # DP transitions
    for i in range(n):
        for last in range(3):
            for v in range(count[0] + 1):
                for k in range(count[1] + 1):
                    if dp[i][last][v][k] == INF:
                        continue

                    # Try to place each character type
                    for j in range(3):
                        if j == 0 and last == 1:
                            continue  # Can't place 'V' after 'K'

                        # Check if we can place this character type
                        if v == count[0] and j == 0:
                            continue
                        if k == count[1] and j == 1:
                            continue
                        if (n - i - 1) - (v + k) == 0 and j == 2:
                            continue

                        # Calculate swaps needed to place this character
                        # The i-th character in the final arrangement
                        # We need to swap past the characters already placed

                        # If we place type j at position i, we need to swap past:
                        # - v characters of type 0 if j == 0
                        # - k characters of type 1 if j == 1
                        # - v + k characters of type 0 and 1 if j == 2
                        swaps = 0

                        if j == 0:
                            swaps = v  # swap past v 'V's that are placed before
                        elif j == 1:
                            swaps = k  # swap past k 'K's that are placed before
                        else:
                            swaps = v + k  # swap past v 'V's and k 'K's

                        # Update DP
                        if j == 0:
                            new_v = v + 1
                            new_k = k
                        elif j == 1:
                            new_v = v
                            new_k = k + 1
                        else:
                            new_v = v
                            new_k = k

                        dp[i + 1][j][new_v][new_k] = min(
                            dp[i + 1][j][new_v][new_k],
                            dp[i][last][v][k] + swaps
                        )

    # Find minimum answer
    answer = INF
    for last in range(3):
        for v in range(count[0] + 1):
            for k in range(count[1] + 1):
                answer = min(answer, dp[n][last][v][k])

    print(answer)

solve()
