import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    n = int(data[1])
    grid = data[2:2+m]

    # Find all blocks
    blocks = {}
    visited = [[False]*len(grid[0]) for _ in range(m)]

    for i in range(m):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j] != '0':
                color = grid[i][j]
                # Find the rectangle
                top, bottom = i, i
                left, right = j, j

                # Expand down
                while bottom + 1 < m and grid[bottom + 1][j] == color:
                    bottom += 1
                # Expand up
                while top - 1 >= 0 and grid[top - 1][j] == color:
                    top -= 1
                # Expand right
                while right + 1 < len(grid[0]) and grid[i][right + 1] == color:
                    right += 1
                # Expand left
                while left - 1 >= 0 and grid[i][left - 1] == color:
                    left -= 1

                # Mark visited
                for x in range(top, bottom + 1):
                    for y in range(left, right + 1):
                        visited[x][y] = True

                # Store block
                blocks[(top, bottom, left, right)] = color

    # Find initial block (contains top-left corner)
    top, bottom, left, right = 0, 0, 0, 0
    for i in range(m):
        for j in range(len(grid[i])):
            if grid[i][j] != '0':
                top, bottom = i, i
                left, right = j, j

                # Expand down
                while bottom + 1 < m and grid[bottom + 1][j] == grid[i][j]:
                    bottom += 1
                # Expand up
                while top - 1 >= 0 and grid[top - 1][j] == grid[i][j]:
                    top -= 1
                # Expand right
                while right + 1 < len(grid[0]) and grid[i][right + 1] == grid[i][j]:
                    right += 1
                # Expand left
                while left - 1 >= 0 and grid[i][left - 1] == grid[i][j]:
                    left -= 1

                # Check if top-left corner is inside this block
                if left <= 0 <= right:
                    break
        else:
            continue
        break

    current_block = (top, bottom, left, right)

    # DP: right, down, left, up
    dp = 0  # 0: right, 1: down, 2: left, 3: up
    # CP: left from DP, right from DP
    cp = 0  # 0: left, 1: right

    # Directions
    directions = [
        (0, 1),  # right
        (1, 0),  # down
        (0, -1), # left
        (-1, 0)  # up
    ]

    # Rotate DP clockwise
    def rotate_dp(dp):
        return (dp + 1) % 4

    # Move from a position
    def move(pos, dp):
        dx, dy = directions[dp]
        nx, ny = pos[0] + dx, pos[1] + dy
        if 0 <= nx < m and 0 <= ny < len(grid[0]) and grid[nx][ny] != '0':
            # Find block containing (nx, ny)
            color = grid[nx][ny]
            top, bottom, left, right = 0, 0, 0, 0
            for i in range(m):
                for j in range(len(grid[i])):
                    if grid[i][j] == color and not visited[i][j]:
                        top, bottom = i, i
                        left, right = j, j

                        # Expand down
                        while bottom + 1 < m and grid[bottom + 1][j] == color:
                            bottom += 1
                        # Expand up
                        while top - 1 >= 0 and grid[top - 1][j] == color:
                            top -= 1
                        # Expand right
                        while right + 1 < len(grid[0]) and grid[i][right + 1] == color:
                            right += 1
                        # Expand left
                        while left - 1 >= 0 and grid[i][left - 1] == color:
                            left -= 1

                        # Mark visited
                        for x in range(top, bottom + 1):
                            for y in range(left, right + 1):
                                visited[x][y] = True

                        # Check if (nx, ny) is inside this block
                        if left <= nx <= right:
                            return (top, bottom, left, right)
            return None
        return None

    # Find the furthest edge in DP direction
    def get_furthest_edge(pos, dp):
        dx, dy = directions[dp]
        if dp == 0:  # right
            return (pos[0], pos[1] + 1)
        elif dp == 1:  # down
            return (pos[0] + 1, pos[1])
        elif dp == 2:  # left
            return (pos[0], pos[1] - 1)
        else:  # up
            return (pos[0] - 1, pos[1])

    # Select the furthest pixel in CP direction
    def get_furthest_pixel(edge, cp, dp):
        # edge is a single pixel
        dx, dy = directions[dp]
        if cp == 0:  # left from DP
            return edge
        else:  # right from DP
