                else:  # right from left = up
                    return (edge[0] - 1, edge[1])
            else:  # up
                if cp == 0:  # left from up = left
                    return (edge[0], edge[1] - 1)
                else:  # right from up = right
                    return (edge[0], edge[1] + 1)

