import sys

def read_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return None
    m = int(data[0])
    n = int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        row = data[idx]
        grid.append(row)
        idx += 1
    return m, n, grid

def find_blocks(grid):
    """Find all blocks (rectangles of same color)"""
    m = len(grid)
    if m == 0:
        return []
    n = len(grid[0])

    visited = [[False] * n for _ in range(m)]
    blocks = []

    for i in range(m):
        for j in range(n):
            if not visited[i][j] and grid[i][j] != '0':
                # Find the block
                color = grid[i][j]
                x1, y1 = i, j
                x2, y2 = i, j

                # Expand to find the rectangle
                while y2 < n and grid[x1][y2] == color:
                    y2 += 1
                while x2 < m and grid[x2][y1] == color:
                    x2 += 1
                while y1 > 0 and grid[x1][y1 - 1] == color:
                    y1 -= 1
                while x1 > 0 and grid[x1 - 1][y1] == color:
                    x1 -= 1

                # Check if this is a rectangle
                is_rectangle = True
                for x in range(x1, x2):
                    for y in range(y1, y2):
                        if grid[x][y] != color:
                            is_rectangle = False
                            break
                    if not is_rectangle:
                        break

                if is_rectangle:
                    blocks.append((x1, y1, x2, y2, color))

                    # Mark visited
                    for x in range(x1, x2):
                        for y in range(y1, y2):
                            visited[x][y] = True

    return blocks

def find_block_index(grid, block):
    """Find the index of a block"""
    m = len(grid)
    n = len(grid[0])

    # Find the top-left corner of the block
    for i in range(block[0], block[2] + 1):
        for j in range(block[1], block[3] + 1):
            if grid[i][j] == block[4]:
                return (i, j)
    return None

def get_next_block(grid, blocks, current_block, dp, cp):
    """Get the next block after one step"""
    # DP: 0-right, 1-down, 2-left, 3-up
    # CP: 0-left, 1-right

    # Find the furthest edge in DP direction
    if dp == 0:  # right
        edge_y = current_block[3]
        edge_x_start = current_block[0]
        edge_x_end = current_block[2]
    elif dp == 1:  # down
        edge_x = current_block[2]
        edge_y_start = current_block[1]
        edge_y_end = current_block[3]
    elif dp == 2:  # left
        edge_y = current_block[1]
        edge_x_start = current_block[0]
        edge_x_end = current_block[2]
    else:  # up
        edge_x = current_block[0]
        edge_y_start = current_block[1]
        edge_y_end = current_block[3]

    # Find the furthest pixel in CP direction
    if dp == 0:  # right
        if cp == 0:  # CP left (up)
            edge_y = current_block[1]
        else:  # CP right (down)
            edge_y = current_block[3]
    elif dp == 1:  # down
        if cp == 0:  # CP left (left)
            edge_x = current_block[0]
        else:  # CP right (right)
            edge_x = current_block[2]
    elif dp == 2:  # left
        if cp == 0:  # CP left (down)
            edge_x = current_block[3]
        else:  # CP right (up)
            edge_x = current_block[1]
    else:  # up
        if cp == 0:  # CP left (right)
            edge_x = current_block[2]
        else:  # CP right (left)
            edge_x = current_block[0]

    # Now find the exact pixel
    if dp == 0:  # right
        if cp == 0:
            # DP right, CP left (up): top-left of edge
            pixel = (current_block[0], current_block[1])
        else:
            # DP right, CP right (down): bottom-left of edge
            pixel = (current_block[0], current_block[3])
    elif dp == 1:  # down
        if cp == 0:
            # DP down, CP left (left): top-left of edge
            pixel = (current_block[0], current_block[1])
        else:
            # DP down, CP right (right): bottom-left of edge
            pixel = (current_block[2], current_block[1])
    elif dp == 2:  # left
        if cp == 0:
            # DP left, CP left (down): top-left of edge
            pixel = (current_block[0], current_block[1])
        else:
            # DP left, CP right (up): bottom-left of edge
            pixel = (current_block[2], current_block[1])
    else:  # up
        if cp == 0:
            # DP up, CP left (right): top-left of edge
            pixel = (current_block[0], current_block[1])
        else:
            # DP up, CP right (left): bottom-left of edge
            pixel = (current_block[0], current_block[3])

    # Try to move in DP direction
    if dp == 0:
        nx, ny = pixel[0], pixel[1] + 1
    elif dp == 1:
        nx, ny = pixel[0] + 1, pixel[1]
    elif dp == 2:
        nx, ny = pixel[0], pixel[1] - 1
    else:  # dp == 3
        nx, ny = pixel[0] - 1, pixel[1]

    # Check if next pixel is valid
    m = len(grid)
    n = len(grid[0])
    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '0':
        # Valid move to new block
        # Find the block that contains the next pixel
        for block in blocks:
            if block[0] <= nx <= block[2] and block[1] <= ny <= block[3]:
                next_block = block
                break
        return next_block, dp, cp
    else:
        # Invalid move
        if cp == 0:
            # CP was left, now points to right
            return current_block, dp, 1
        else:
            # CP was right, now points to left and DP rotates clockwise
            # DP right -> down -> left -> up -> right
            new_dp = (dp + 1) % 4
            return current_block, new_dp, 0

def solve():
    data = read_input()
    if not data:
        return
    m, n, grid = data

    # Find all blocks
    blocks = find_blocks(grid)

    # Find the initial block (contains top-left corner)
    initial_block = None
    for block in blocks:
        if block[0] <= 0 <= block[2] and block[1] <= 0 <= block[3]:
            initial_block = block
            break

    # Initial state
    current_block = initial_block
    dp = 0  # right
    cp = 0  # left

    for _ in range(n):
        current_block, dp, cp = get_next_block(grid, blocks, current_block, dp, cp)

    # Output the color of the current block
    print(current_block[4])

if __name__ == "__main__":
    solve()
