def find_missing_game(n, games):
    """Find the missing game result."""

    # Create a dictionary of who each participant has beaten
    beaten = {i: set() for i in range(1, n + 1)}

    for winner, loser in games:
        beaten[winner].add(loser)

    # Find the pair of participants who haven't played each other
    for winner in range(1, n + 1):
        for loser in range(1, n + 1):
            if winner != loser and loser not in beaten[winner]:
                # Check if winner should beat loser (if all losers of winner are also losers of loser)
                if winner in beaten[loser]:
                    # winner should lose to loser, but they didn't play yet
                    # If loser has beaten everyone winner has beaten, then loser should win
                    if len(beaten[loser]) == len(beaten[winner]) and beaten[winner].issubset(beaten[loser]):
