import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    a = [int(next(it)) for _ in range(n)]

    # Create a dictionary for rules: (x, y) -> c
    rules = {}
    for _ in range(k):
        x = int(next(it)) - 1  # 0-indexed
        y = int(next(it)) - 1
        c = int(next(it))
        rules[(x, y)] = c

    # Initialize DP: dp[i][mask][last] = max satisfaction
    # We'll use a dictionary of dictionaries
    dp = {0: {0: {None: 0}}}  # 0 dishes eaten, empty set, no last dish

    for i in range(m):
        for mask in dp[i]:
            for last in dp[i][mask]:
                current_satisfaction = dp[i][mask][last]

                # Try adding each unused dish
                for j in range(n):
                    if not (mask & (1 << j)):  # j not in mask
                        new_mask = mask | (1 << j)
                        new_satisfaction = current_satisfaction + a[j]

                        # Check if there's a rule for last -> j
                        if last is not None and (last, j) in rules:
                            new_satisfaction += rules[(last, j)]

                        # Update DP
                        if new_mask not in dp[i+1]:
                            dp[i+1][new_mask] = {}
                        if last not in dp[i+1][new_mask]:
                            dp[i+1][new_mask][last] = -float('inf')
                        dp[i+1][new_mask][last] = max(
                            dp[i+1][new_mask][last], new_satisfaction)

    # Find the maximum satisfaction among all states with m dishes eaten
    max_satisfaction = -float('inf')
    for mask in dp[m]:
        for last in dp[m][mask]:
            max_satisfaction = max(max_satisfaction, dp[m][mask][last])

    print(max_satisfaction)

if __name__ == "__main__":
    solve()
