import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    a = [int(next(it)) for _ in range(n)]

    # Create a dictionary for rules: (x, y) -> c
    rules = {}
    for _ in range(k):
        x = int(next(it)) - 1  # 0-indexed
        y = int(next(it)) - 1
        c = int(next(it))
        rules[(x, y)] = c

    # Initialize DP: dp[i] = {mask: {last: max_satisfaction}}
    dp = [None] * (m + 1)
    dp[0] = {0: {None: 0}}

    # Process transitions for each i from 0 to m-1
    for i in range(m):
        # Get current states
        current = dp[i]
        next_dp = dp[i+1] if dp[i+1] is not None else {}

        # Process each state
        for mask in current:
            for last in current[mask]:
                current_satisfaction = current[mask][last]

                # Try adding each unused dish
                for j in range(n):
                    if not (mask & (1 << j)):  # j not in mask
                        new_mask = mask | (1 << j)
                        new_satisfaction = current_satisfaction + a[j]

                        # Check if there's a rule for last -> j
                        if last is not None and (last, j) in rules:
                            new_satisfaction += rules[(last, j)]

                        # Update next_dp
                        if new_mask not in next_dp:
                            next_dp[new_mask] = {}

                        # Update the last dish and satisfaction
                        if last not in next_dp[new_mask]:
                            next_dp[new_mask][last] = new_satisfaction
                        else:
                            next_dp[new_mask][last] = max(
                                next_dp[new_mask][last], new_satisfaction)

        # Set dp[i+1] to the processed states
        if next_dp:
            dp[i+1] = next_dp
        else:
            dp[i+1] = {}

    # Find the maximum satisfaction among all states with m dishes eaten
    max_satisfaction = -float('inf')
    for mask in dp[m]:
        for last in dp[m][mask]:
            max_satisfaction = max(max_satisfaction, dp[m][mask][last])

    print(max_satisfaction)

