import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    a = [int(next(it)) for _ in range(n)]

    # Create a dictionary for rules: (x, y) -> c
    rules = {}
    for _ in range(k):
        x = int(next(it)) - 1  # 0-indexed
        y = int(next(it)) - 1
        c = int(next(it))
        rules[(x, y)] = c

    # Initialize DP for 0 dishes eaten
    dp = {0: {0: {None: 0}}}

    # Process each state
    for i in range(m):
        # Get current states
        current = dp[i]

        # Process transitions to i+1
        next_states_dict = {}
        for mask in current:
            for last in current[mask]:
                current_satisfaction = current[mask][last]

                # Add each unused dish
                for j in range(n):
                    if not (mask & (1 << j)):
                        new_mask = mask | (1 << j)
                        new_satisfaction = current_satisfaction + a[j]

                        # Check for rules
                        if last is not None and (last, j) in rules:
                            new_satisfaction += rules[(last, j)]

                        # Update the new state
                        if new_mask not in next_states_dict:
                            next_states_dict[new_mask] = {}

                        # Update the last dish and satisfaction
                        # If last not present, set directly
                        if last not in next_states_dict[new_mask]:
                            next_states_dict[new_mask][last] = new_satisfaction
                        else:
                            next_states_dict[new_mask][last] = max(
                                next_states_dict[new_mask][last], new_satisfaction)

        dp[i+1] = next_states_dict

    # Find maximum satisfaction for m dishes
    max_satisfaction = -float('inf')
    for mask in dp[m]:
        for last in dp[m][mask]:
            max_satisfaction = max(max_satisfaction, dp[m][mask][last])

    print(max_satisfaction)

