import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    m = int(data[n+1])
    b = list(map(int, data[n+2:n+2+m]))

    sum_a = sum(a)
    sum_b = sum(b)
    diff = sum_a - sum_b

    # 0 swaps
    min_diff = abs(diff)
    best_swaps = []

    # 1 swap
    for i in range(n):
        for j in range(m):
            new_diff = abs(diff - 2 * (a[i] - b[j]))
            if new_diff < min_diff:
                min_diff = new_diff
                best_swaps = [(i+1, j+1)]

    # 2 swaps
    for i in range(n):
        for j in range(m):
            for k in range(n):
                for l in range(m):
                    # Swap (i, j) then (k, l)
