import sys
import math

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Sort the array
    a.sort()

    # Total number of ways to choose 6 distinct numbers from n
    total = 0

    # For each subset of 6 numbers
    for i in range(n - 5):
        for j in range(i + 1, n - 4):
            for k in range(j + 1, n - 3):
                for l in range(k + 1, n - 2):
                    for m in range(l + 1, n - 1):
                        for p in range(m + 1, n):
                            # We have 6 numbers: a[i], a[j], a[k], a[l], a[m], a[p]
                            # Sort them
                            nums = [a[i], a[j], a[k], a[l], a[m], a[p]]
                            nums.sort()

                            # Count valid assignments
                            count = 0

                            # Choose 3 for Andrew, 3 for Jerry
                            for andrew_idx in range(1 << 6):
                                if bin(andrew_idx).count('1') == 3:
                                    # Get Andrew's numbers
                                    andrew = [nums[idx] for idx in range(6) if andrew_idx & (1 << idx)]

                                    # Get Jerry's numbers
                                    jerry = [nums[idx] for idx in range(6) if not (andrew_idx & (1 << idx))]

                                    # Assign largest to a1, next to a2, smallest to a3 for Andrew
                                    andrew_sorted = sorted(andrew, reverse=True)
                                    a1, a2, a3 = andrew_sorted

                                    # Assign largest to j1, next to j2, smallest to j3 for Jerry
                                    jerry_sorted = sorted(jerry, reverse=True)
                                    j1, j2, j3 = jerry_sorted

                                    # Check win conditions
                                    if a1 > j1 and a2 > j2 and j3 > a3:
                                        # Check sum condition
                                        if j1 + j2 + j3 > a1 + a2 + a3:
                                            count += 1

                            total += count

    # Total number of ways to draw 3 rounds
    # First round: choose 2 balls, Andrew wins
    # Second round: choose 2 balls from remaining, Andrew wins
