import sys

def solve():
    while True:
        line = sys.stdin.readline().strip()
        if not line:
            break

        if line == "start":
            # Binary search to find the smallest multiple of a
            low = 1
            high = 2 * 10**9
            while low < high:
                mid = (low + high) // 2
                print(f"? 0 {mid}")
                sys.stdout.flush()

                resp = sys.stdin.readline().strip()
                if resp == "x":
                    # mid is a multiple of a, try smaller
                    high = mid
                elif resp == "y":
                    # mid is not a multiple of a, try larger
                    low = mid + 1
                else:
                    # e or mistake
                    return

            # Now low == high, it's the smallest multiple of a
            # Find the largest number less than low that is not a multiple of a
            # We can use binary search again or just check low - 1
            # Actually, if low is a multiple of a, then low - 1 is not a multiple of a
            # So we can just check if low - 1 is not a multiple
            if low == 0:
                a = 1
            else:
                # Check if low - 1 is a multiple of a
                print(f"? 0 {low - 1}")
                sys.stdout.flush()

                resp = sys.stdin.readline().strip()
                if resp == "x":
                    # low - 1 is a multiple of a, this shouldn't happen
                    a = low // 2
                elif resp == "y":
                    # low - 1 is not a multiple of a
                    a = low // 1
                else:
                    return

            print(f"! {a}")
            sys.stdout.flush()
        elif line == "mistake":
            return
        elif line == "end":
            return

solve()
