import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    c = [int(next(it)) for _ in range(n)]

    # Read the table
    table = []
    for i in range(n):
        row = [int(next(it)) for _ in range(c[i])]
        table.append(row)

    # Let's use a simple bubble sort to sort each row
    swaps = []

    # Sort each row
    for i in range(n):
        row_len = c[i]
        # Use bubble sort
        for j in range(row_len - 1):
            if table[i][j] > table[i][j+1]:
                swaps.append((i+1, j+1, i+1, j+2))
                table[i][j], table[i][j+1] = table[i][j+1], table[i][j]

    print(len(swaps))
    for x, y, p, q in swaps:
        print(x, y, p, q)

if __name__ == "__main__":
    solve()
"}

