import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        s = data[idx]
        idx += 1

        # Trace the robot's path without obstacle
        path = [(0, 0)]
        x, y = 0, 0
        for ch in s:
            if ch == 'L':
                x -= 1
            elif ch == 'R':
                x += 1
            elif ch == 'D':
                y -= 1
            elif ch == 'U':
                y += 1
            path.append((x, y))

        # Try each position in the path (excluding start)
        found = False
        for i in range(1, len(path)):
            ox, oy = path[i]

            # Simulate with obstacle at (ox, oy)
            x, y = 0, 0
            for ch in s:
                if ch == 'L':
                    nx, ny = x - 1, y
                elif ch == 'R':
                    nx, ny = x + 1, y
                elif ch == 'D':
                    nx, ny = x, y - 1
                elif ch == 'U':
                    nx, ny = x, y + 1
                else:
                    nx, ny = x, y

                # Check if we hit the obstacle
                if nx == ox and ny == oy:
                    # Stay at current position
                    x, y = x, y
                else:
                    x, y = nx, ny

            if x == 0 and y == 0:
                print(f"{ox} {oy}")
                found = True
                break

        if not found:
            print("0 0")

if __name__ == "__main__":
    solve()
