    s = sys.stdin.read().strip()
    n = len(s)

    # Count lowercase letters before each position
    lowercase_before = [0] * n
    count = 0
    for i in range(n):
        if s[i].islower():
            count += 1
        lowercase_before[i] = count

    # Count uppercase letters from each position to the end
    uppercase_after = [0] * n
    count = 0
    for i in range(n-1, -1, -1):
        if s[i].isupper():
            count += 1
        uppercase_after[i] = count

    # Find minimum changes
    min_changes = float('inf')
    for i in range(n):
        # Split after position i (0..i uppercase, i+1..n-1 lowercase)
        changes = lowercase_before[i] + uppercase_after[i+1]
        if changes < min_changes:
            min_changes = changes

    print(min_changes)

