class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)

    def update(self, idx, delta=1):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res


def count_greater(ft, value):
    """Count elements > value"""
    return ft.query(ft.n) - ft.query(value)

def count_less(ft, value):
    """Count elements < value"""
    return ft.query(value - 1)


def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Find the maximum value to determine Fenwick Tree size
    max_val = max(a)

    # Count left[j] for each element (elements to the left that are greater)
    left = [0] * n
    ft_left = FenwickTree(max_val)
    for i in range(n):
        left[i] = count_greater(ft_left, a[i])
        ft_left.update(a[i])

    # Count right[j] for each element (elements to the right that are less)
    right = [0] * n
    ft_right = FenwickTree(max_val)
    for i in range(n - 1, -1, -1):
        right[i] = count_less(ft_right, a[i])
        ft_right.update(a[i])

    # Calculate total weakness
    weakness = 0
    for i in range(n):
        weakness += left[i] * right[i]

    print(weakness)

solve()
