def solve():
    while True:
        line = sys.stdin.readline().strip()
        if not line:
            continue
        if line == "start":
            # Binary search to find a
            low = 1
            high = 10**9

            while low < high:
                mid = (low + high) // 2
                # Ask (mid, mid + 1)
                print(f"? {mid} {mid + 1}")
                sys.stdout.flush()
                res = sys.stdin.readline().strip()

                if res == "x":
                    # mid % a >= (mid+1) % a
                    # This means mid >= mid+1 (mod a), which implies a > mid
                    low = mid + 1
                elif res == "y":
                    # mid % a < (mid+1) % a
                    # This means a <= mid
                    high = mid
                else:
                    print("! -1")
                    sys.stdout.flush()
                    return

