            # Push 'pair' to the structure
            structure.append('pair')

            # We need two arguments for 'pair'
            # Check if we have two arguments
            if len(stack) >= 2:
                # Pop the two arguments
                arg2 = stack.pop()
                arg1 = stack.pop()

                # Create a pair node with these arguments
                pair_node = ['pair', arg1, arg2]
                stack.append(pair_node)
            else:
                # Not enough arguments yet
                stack.append(None)

    # After parsing, check if we have a valid structure
    if len(stack) != 1 or stack[0] is None:
        print("Error occurred")
        return

    # Now we have a structure, let's verify it stores exactly n integers
