import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    m = int(next(it))

    words = {}
    for i in range(n):
        word = next(it)
        words[word] = i + 1  # map word to its index (1-based)

    costs = [0] * (n + 1)  # 1-indexed
    for i in range(1, n + 1):
        costs[i] = int(next(it))

    # For each group, find the minimum cost
    min_cost_per_group = {}
    for _ in range(k):
        x = int(next(it))
        group = []
        for _ in range(x):
            idx = int(next(it))
            group.append(idx)
        # Find the minimum cost in this group
        min_cost = min(costs[i] for i in group)
        min_cost_per_group[tuple(sorted(group))] = min_cost

    # Read message
    message = []
    for _ in range(m):
        word = next(it)
        message.append(word)

    # Calculate total cost
    total = 0
    for word in message:
        idx = words[word]
        # Find which group this word belongs to
        for group in min_cost_per_group:
            if idx in group:
                total += min_cost_per_group[group]
                break

    print(total)

if __name__ == "__main__":
    solve()
