from collections import deque

def inverse_permutation(p):
    n = len(p)
    inv = [0] * (n + 1)  # 1-indexed
    for i in range(1, n + 1):
        inv[p[i - 1]] = i
    return inv

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    q = list(map(int, data[2:2+n]))
    s = list(map(int, data[2+n:2+2*n]))

    # Start with identity permutation
    identity = [i for i in range(1, n + 1)]

    # BFS to find all reachable states from identity up to k moves
    queue = deque()
    visited = set()
    queue.append((identity, 0))
    visited.add(tuple(identity))

    # Check if we can reach s in exactly k moves and s does not appear before
    can_reach_k = False

    for _ in range(k):
        # Get all states from the current level
        current_set = []
        while queue:
            curr, curr_moves = queue.popleft()

            if curr_moves < k:
                current_set.append(curr)

        # Process next states (k-th move, if any)
        next_set = []
        for curr in current_set:
            if len(next_set) < k - 1:
                # Apply q
                next_q = [curr[q[i] - 1] for i in range(n)]
                if tuple(next_q) not in visited:
                    visited.add(tuple(next_q))
                    next_set.append(next_q)

            # Apply inverse q
            inv_q = inverse_permutation(q)
            next_inv_q = [curr[inv_q[i] - 1] for i in range(n)]
            if tuple(next_inv_q) not in visited:
                visited.add(tuple(next_inv_q))
                next_set.append(next_inv_q)

        queue = deque(next_set)

    # After k moves, check if we have s and it's not earlier
    for curr in current_set:
        if tuple(curr) == tuple(s):
            can_reach_k = True
            break

    if can_reach_k and k > 0:
        if any(tuple(curr) == tuple(s) for curr in [identity] + current_set):
            print("NO")
        else:
            print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
