import sys

def multiply(a, b, mod):
    """Matrix multiplication"""
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if a[i][k] == 0:
                continue
            for j in range(n):
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
    return result

def matrix_pow(mat, power, mod):
    """Matrix exponentiation"""
    n = len(mat)
    # Initialize result as identity matrix
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    while power > 0:
        if power % 2 == 1:
            result = multiply(result, mat, mod)
        mat = multiply(mat, mat, mod)
        power //= 2
    return result

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    b = int(data[1])
    k = int(data[2])
    x = int(data[3])

    digits = list(map(int, data[4:4+n]))

    # Count occurrences of each digit
    cnt = [0] * 10
    for d in digits:
        cnt[d] += 1

    # Build transition matrix: T[i][j] = number of ways to go from state i to state j
    mod = 10**9 + 7
    T = [[0] * x for _ in range(x)]
    for i in range(x):
        for d in range(1, 10):
            if cnt[d] == 0:
                continue
            j = (i * 10 + d) % x
            T[i][j] = (T[i][j] + cnt[d]) % mod

    # Raise matrix to b-th power
    T_pow = matrix_pow(T, b, mod)

    # Answer: number of ways to start at state 0 and end at state k
    print(T_pow[0][k] % mod)

