        min_time = [float('inf')] * (len(day) + 1)

        # Case: skip 0 lessons
        time = 0
        for c in day:
            if c == '1':
                time += 1
        min_time[0] = time

        # Try skipping t lessons for 1 <= t <= len(day)
        for t in range(1, len(day) + 1):
            # Try all possible ways to skip t lessons
            for start in range(len(day)):
