def find_missing_game(n, games):
    """Find the missing game result."""
    # Create a set of all pairs
    all_pairs = set()
    for i in range(1, n+1):
        for j in range(1, n+1):
            if i < j:
                all_pairs.add((i, j))

    # Create a set of played pairs
    played_pairs = set()
    for winner, loser in games:
        played_pairs.add((min(winner, loser), max(winner, loser)))

    # Find the missing pair
    missing_pair = (all_pairs - played_pairs).pop()

    # Determine the winner of the missing game
    # The winner should be the one with the fewest losses
    losses = {i: 0 for i in range(1, n+1)}

    for winner, loser in games:
        losses[loser] += 1

    winner_of_missing = min(losses, key=losses.get)
    loser_of_missing = max(losses, key=losses.get)

    # The missing game is winner_of_missing beats loser_of_missing
    # But we already have the pair from missing_pair
    # So we just need to check if the first is the winner
    if winner_of_missing == missing_pair[0]:
        return (missing_pair[0], missing_pair[1])
    else:
        return (missing_pair[1], missing_pair[0])

