def maximize_sum_of_squares(n, r):
    # Strategy: place points at (r, 0), (-r, 0), (0, r), (0, -r), etc.
    # For even n, place n/2 pairs at opposite ends
    # For odd n, place (n-1)/2 pairs and one point at (0, 0)

    # Find integer coordinates that maximize distance squared
    max_distance_squared = 0
    best_point = (0, 0)

    # Check all integer points within the circle
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x**2 + y**2 <= r**2:
                distance_squared = x**2 + y**2
                if distance_squared > max_distance_squared:
                    max_distance_squared = distance_squared
                    best_point = (x, y)

    # Place one point at best_point
    points = [best_point]

    # Place remaining points at symmetric positions
    for i in range(1, n):
        # Place a point at a random integer point within the circle
        # that's not already placed
        placed = set(points)
        found = False

        for x in range(-r, r + 1):
            for y in range(-r, r + 1):
                if x**2 + y**2 <= r**2 and (x, y) not in placed:
                    points.append((x, y))
                    found = True
                    break
            if found:
                break

    # Calculate sum of squared distances
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            total += dx**2 + dy**2

    return total, points

