    k, b, n = map(int, input().split())
    digits = list(map(int, input().split()))

    # We want to count substrings where digital_root(x) = b
    # x is the number represented by the substring

    # Let's directly calculate for each substring
    count = 0

    # Single digit substrings
    if b in digits:
        count += digits.count(b)

    # Multi-digit substrings
    # We need to calculate the digital root for each substring

    for i in range(n):
        value = digits[i]
        if value == b:
            count += 1
        # Extend to longer substrings
        for j in range(i + 1, n):
            value = value * k + digits[j]
            dr = digital_root(value, k)
            if dr == b:
                count += 1

    print(count)

