def apply_shift(s, x):
    """Apply shift x to string s"""
    if x == 0:
        return s
    return s[-x:][::-1] + s[:-x]

def trace_shifts(s, shifts):
    """Apply a sequence of shifts to string s and return the result"""
    result = s
    for shift in shifts:
        result = apply_shift(result, shift)
    return result

def solve():
    n = int(input().strip())
    s = input().strip()
    t = input().strip()

    # Check if already equal
    if s == t:
        print(0)
        return

    # BFS to find shortest sequence of shifts
    from collections import deque

    # State: (current_string, path)
    queue = deque([(s, [])])
    visited = {s}

    while queue:
        current, path = queue.popleft()

        # Try all possible shifts
        for shift in range(n + 1):
            new_str = apply_shift(current, shift)

            if new_str == t:
                print(len(path) + 1)
                print(" ".join(map(str, path + [shift])))
                return

            if new_str not in visited:
                visited.add(new_str)
                queue.append((new_str, path + [shift]))

    print(-1)

