import sys

def is_available(occupied, start, end):
    """Check if all days from start to end (inclusive) are available"""
    for day in range(start, end + 1):
        if day in occupied:
            return False
    return True

def find_earliest_block(occupied, di):
    """Find the smallest starting day x such that [x, x+di-1] is available"""
    x = 1
    while True:
        if is_available(occupied, x, x + di - 1):
            return x
        x += 1

