    """Check if t is a subsequence of s"""
    it = iter(s)
    return all(c in it for c in t)

def solve():
    s = input().strip()
    t = input().strip()

    max_length = 0

    # Try removing every possible contiguous substring
    for i in range(len(s)):
        for j in range(i, len(s)):
            # Remove substring s[i:j+1]
            modified_s = s[:i] + s[j+1:] if i != j else s[:i] + s[j+1:]  # Handle i == j case

            # Check if t is still a subsequence
            if is_subsequence(t, modified_s):
                length = j - i + 1
                if length > max_length:
                    max_length = length

    print(max_length)

