def count_changes(s, split_point):
    """
    Count the number of changes needed to make all letters before split_point uppercase
    and all letters from split_point onwards lowercase.
    """
    changes = 0

    # Process prefix (before split_point)
    for i in range(split_point):
        if s[i].islower():
            changes += 1  # need to change to uppercase

    # Process suffix (from split_point)
    for i in range(split_point, len(s)):
        if s[i].isupper():
            changes += 1  # need to change to lowercase

    return changes

def solve():
    s = input().strip()

    min_changes = len(s)  # worst case: all letters need to be changed

    # Try all possible split points (including before first character and after last character)
    for split_point in range(len(s) + 1):
        changes = count_changes(s, split_point)
        if changes < min_changes:
            min_changes = changes

    print(min_changes)

solve()
